from itertools import cycle
import pytest
from transformers import AutoTokenizer
from aphrodite import SamplingParams
from ...utils import create_new_process_for_each_test
from .conftest import get_output_from_llm_generator, run_equality_correctness_test
@pytest.mark.parametrize('common_llm_kwargs', [{'model': 'JackFram/llama-68m', 'enforce_eager': True}])
@pytest.mark.parametrize('per_test_common_llm_kwargs', [{'speculative_config': {'model': 'JackFram/llama-68m', 'num_speculative_tokens': 5}, 'enable_chunked_prefill': False}, {'speculative_config': {'model': 'JackFram/llama-68m', 'num_speculative_tokens': 5}, 'enable_chunked_prefill': True, 'max_num_batched_tokens': 4, 'max_num_seqs': 4}, {}])
@pytest.mark.parametrize('test_llm_kwargs', [{}])
@pytest.mark.parametrize('batch_size', [1, 32])
@pytest.mark.parametrize('seed', [1])
@create_new_process_for_each_test()
def test_spec_decode_e2e_with_detokenization(test_llm_generator, batch_size: int):
    output_len = 32
    temperature = 0.0
    prompts = ['Hello, my name is', 'The president of the United States is', 'The capital of France is', 'The future of AI is']
    prompts = [prompt for prompt, _ in zip(cycle(prompts), range(batch_size))]
    sampling_params = SamplingParams(max_tokens=output_len, ignore_eos=True, temperature=temperature)
    batch_tokens, batch_token_ids, _ = get_output_from_llm_generator(test_llm_generator, prompts, sampling_params)
    assert len(batch_token_ids) == len(prompts)
    assert [len(token_ids) for token_ids in batch_token_ids] == [output_len] * batch_size
    tok = AutoTokenizer.from_pretrained('JackFram/llama-68m')
    for actual_tokens, actual_token_ids in zip(batch_tokens, batch_token_ids):
        expected_tokens = tok.decode(actual_token_ids)
        print(f'actual_token_ids={actual_token_ids!r}')
        assert actual_tokens.strip() == expected_tokens.strip()
