@pytest.mark.parametrize('batch_size', [1])
@pytest.mark.parametrize('seed', [1])
@create_new_process_for_each_test()
def test_spec_decode_e2e_greedy_correctness_tiny_model_bs1(aphrodite_runner, common_llm_kwargs, per_test_common_llm_kwargs, baseline_llm_kwargs, test_llm_kwargs, batch_size: int, output_len: int, seed: int):
    ensure_all_accepted = per_test_common_llm_kwargs.get('model_name') == test_llm_kwargs.get('speculative_config')['model']
    run_equality_correctness_test(aphrodite_runner, common_llm_kwargs, per_test_common_llm_kwargs, baseline_llm_kwargs, test_llm_kwargs, batch_size, max_output_len=output_len, seed=seed, prompt_logprobs=2, logprobs=2, disable_logprobs=False, temperature=0.0, ensure_all_accepted=ensure_all_accepted)
